import subprocess,pathlib
nu=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); ours='executable.cmd'
cases=['open sample.json | get name','open sample.csv | length','open sample.csv | get a','let x = 5; "'$x * 3'"','[1 2 3] | math avg','[2 3 4] | math product','"'$env.PWD'"']
for c in cases:
 a=subprocess.run([nu,'-n','-c',c],capture_output=True); b=subprocess.run([ours,'-n','-c',c],capture_output=True)
 print(('OK' if (a.returncode,a.stdout,a.stderr)==(b.returncode,b.stdout,b.stderr) else 'DIFF'),c)
 if a.stdout"'!=b.stdout: print(repr(a.stdout),repr(b.stdout))
 if a.stderr!=b.stderr: print(repr(a.stderr),repr(b.stderr))
'"'@ | python -; Remove-Item sample.json,sample.csv; & 'C:\\Program Files\\Git\\bin\\bash.exe' ./compile.sh; & 'C:\\Program Files\\Git\\bin\\bash.exe' ./compile.sh; Get-ChildItem executable* | Select-Object Name,Length"

